async function mockDetails(context: BrowserContext) {
  await context.route("**/api/search?*", (route) =>
    route.fulfill({
      json: {
        entities: [
          {
            id: "1",
            name: member.name,
            kind: "MP",
            funder_kind: null,
            match_source: { kind: "name" },
          },
